CREATE TABLE volunteers ( id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL UNIQUE, first_name TEXT NOT NULL, last_name TEXT NOT NULL, phone TEXT, status TEXT, specialty TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE TABLE volunteer_signups ( id INTEGER PRIMARY KEY AUTOINCREMENT, exam_id INTEGER NOT NULL REFERENCES exams(id) ON DELETE CASCADE, volunteer_id INTEGER NOT NULL REFERENCES volunteers(id) ON DELETE CASCADE, roles TEXT NOT NULL DEFAULT '[]', halfdays TEXT NOT NULL DEFAULT '[]', note TEXT, code TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE (exam_id, volunteer_id) );
CREATE TABLE assignments ( id INTEGER PRIMARY KEY AUTOINCREMENT, exam_id INTEGER NOT NULL REFERENCES exams(id) ON DELETE CASCADE, signup_id INTEGER NOT NULL REFERENCES volunteer_signups(id) ON DELETE CASCADE, day TEXT NOT NULL, half TEXT NOT NULL, role TEXT NOT NULL, station_id INTEGER REFERENCES stations(id) ON DELETE SET NULL, UNIQUE (exam_id, signup_id, day, half) );
CREATE TABLE calibrations ( id INTEGER PRIMARY KEY AUTOINCREMENT, exam_id INTEGER NOT NULL REFERENCES exams(id) ON DELETE CASCADE, station_id INTEGER NOT NULL REFERENCES stations(id) ON DELETE CASCADE, scenario TEXT, video_url TEXT, reference TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE (station_id) );
CREATE TABLE calibration_answers ( id INTEGER PRIMARY KEY AUTOINCREMENT, calibration_id INTEGER NOT NULL REFERENCES calibrations(id) ON DELETE CASCADE, signup_id INTEGER NOT NULL REFERENCES volunteer_signups(id) ON DELETE CASCADE, answers TEXT NOT NULL DEFAULT '{}', score REAL, ref_score REAL, agreement REAL, created_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE (calibration_id, signup_id) );
CREATE INDEX idx_assign_exam ON assignments(exam_id, day, half);
